const languageContext = createContext<{
  language: LanguageCode;
  preference: LanguagePreference;
  setPreference: (value: LanguagePreference) => void;
  t: (key: string, values?: MessageValues) => string;
  languageLabel: string;
}>({
  language: 'zh-Hans',
  preference: 'zh-Hans',
  setPreference: () => undefined,
  t: (key, values) => interpolate(zhHans[key] ?? key, values),
  languageLabel: '简体中文',
});

function interpolate(template: string, values?: MessageValues): string {
  if (!values) return template;
  return template.replace(/\{(\w+)\}/g, (_, key: string) => String(values[key] ?? `{${key}}`));
}

export function I18nProvider({ children }: { children: ReactNode }) {
  const [preference, setPreferenceState] = useState<LanguagePreference>(() => readLanguagePreference());
  const language = preference === 'system'
    ? detectSystemLanguage(typeof navigator === 'undefined' ? '' : navigator.language)
    : preference;
  const setPreference = (value: LanguagePreference) => {
    setPreferenceState(value);
    if (typeof window !== 'undefined') window.localStorage.setItem(LANGUAGE_STORAGE_KEY, value);
  };
  const languageLabel = preference === 'system'
    ? (translations[language]['settings.followSystem'] ?? zhHans['settings.followSystem'])
    : LANGUAGE_OPTIONS.find((option) => option.value === preference)?.nativeLabel
      ?? LANGUAGE_OPTIONS.find((option) => option.value === language)?.nativeLabel
      ?? '简体中文';
  const value = useMemo(() => ({
    language,
    preference,
    setPreference,
    languageLabel,
    t: (key: string, values?: MessageValues) => interpolate(translations[language][key] ?? zhHans[key] ?? key, values),
  }), [language, preference, languageLabel]);

  useEffect(() => {
    document.documentElement.lang = language;
  }, [language]);

  return <languageContext.Provider value={value}>{children}</languageContext.Provider>;
}

export function useI18n() {
  return useContext(languageContext);
}
